const j=u=>fetch('/w/api.php?format=json&'+u).then(r=>r.json());
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const seen=new Set(),files=new Set();let queue=[['Category:Mercedes-Benz_Museum',0]];let ncat=0;
while(queue.length&&ncat<400){const [c,d]=queue.shift();if(seen.has(c))continue;seen.add(c);ncat++;
 let cont='';do{const r=await j('action=query&list=categorymembers&cmlimit=500&cmprop=title|type&cmtitle='+encodeURIComponent(c)+cont);
  for(const m of r.query.categorymembers){if(m.type==='subcat'&&d<4)queue.push([m.title,d+1]);else if(m.type==='file')files.add(m.title);}
  cont=r.continue?'&cmcontinue='+encodeURIComponent(r.continue.cmcontinue):'';await sleep(150);}while(cont);}
window.__mbm={files:[...files],cats:[...seen]};
const hits=[...files].filter(f=>/slk|r ?170|vario|sl[ck]-klasse/i.test(f));
`cats ${ncat} files ${files.size} queue ${queue.length}\n`+hits.join('\n')+'\nCATS w/ SL: '+[...seen].filter(c=>/sl|roadster|legend 6|r170/i.test(c)).join(' | ')

