window.__mbm={done:false,files:new Set(),seen:new Set(),err:null};
(async()=>{try{const j=u=>fetch('/w/api.php?format=json&'+u).then(r=>r.json());
const sleep=ms=>new Promise(r=>setTimeout(r,ms));const S=window.__mbm;let queue=[['Category:Mercedes-Benz_Museum',0]];
while(queue.length&&S.seen.size<500){const [c,d]=queue.shift();if(S.seen.has(c))continue;S.seen.add(c);
 let cont='';do{const r=await j('action=query&list=categorymembers&cmlimit=500&cmprop=title|type&cmtitle='+encodeURIComponent(c)+cont);
  for(const m of r.query.categorymembers){if(m.type==='subcat'&&d<4)queue.push([m.title,d+1]);else if(m.type==='file')S.files.add(m.title);}
  cont=r.continue?'&cmcontinue='+encodeURIComponent(r.continue.cmcontinue):'';await sleep(200);}while(cont);}
S.left=queue.length;}catch(e){window.__mbm.err=String(e)}window.__mbm.done=true;})();'started'

