content.content:
// Fit a pinhole camera to a museum photo from 3D↔2D point correspondences (Levenberg–Marquardt).
// Usage: node tools/fit-photo-camera.mjs tools/photo-fits/540k.json
// Output: the photo.cam line to paste into stops/<slug>/car.js, plus per-point residuals in px.
// Camera parameters p = [cx, cy, cz (mm), yaw, pitch, roll (rad), f (px)]; no lens distortion; principal point = image centre.
// Optional: rollPenalty (keeps roll near 0), focalPrior { f, w } (pulls f towards a typical lens when depth cues are weak).
import { readFileSync } from "node:fs";
import { basis as cameraBasis } from "./camera.mjs";

const cfg = JSON.parse(readFileSync(process.argv[2], "utf8"));
const CX = cfg.image.width / 2, CY = cfg.image.height / 2;
const P = cfg.points.map(q => [q.X, q.px, q.w ?? 1]);

const basis = ([, , , yaw, pitch, roll]) => cameraBasis(yaw, pitch, roll);
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
function project(p, X) {
  const { f, r, u } = basis(p), d = [X[0] - p[0], X[1] - p[1], X[2] - p[2]], z = dot(d, f);
  return [CX + p[6] * dot(d, r) / z, CY - p[6] * dot(d, u) / z];
}
function residuals(p) {
  const out = [];
  for (const [X, x, w] of P) { const q = project(p, X); out.push(w * (q[0] - x[0]), w * (q[1] - x[1])); }
  if (cfg.rollPenalty) out.push(p[5] * cfg.rollPenalty);   // keeps the horizon level when points are few
  if (cfg.focalPrior) out.push((p[6] - cfg.focalPrior.f) * cfg.focalPrior.w);   // near-planar points leave f vs distance loose
  return out;
}
const sq = r => r.reduce((a, v) => a + v * v, 0);
function solveLinear(A, b) {
  const n = b.length, M = A.map((row, i) => [...row, b[i]]);
  for (let k = 0; k < n; k++) {
    let piv = k; for (let i = k + 1; i < n; i++) if (Math.abs(M[i][k]) > Math.abs(M[piv][k])) piv = i;
    [M[k], M[piv]] = [M[piv], M[k]];
    for (let i = k + 1; i < n; i++) { const m = M[i][k] / M[k][k]; for (let j = k; j <= n; j++) M[i][j] -= m * M[k][j]; }
  }
  const x = Array(n).fill(0);
  for (let i = n - 1; i >= 0; i--) { let s = M[i][n]; for (let j = i + 1; j < n; j++) s -= M[i][j] * x[j]; x[i] = s / M[i][i]; }
  return x;
}
function levenbergMarquardt(p) {
  let lam = 1e-3;
  for (let it = 0; it < 500; it++) {
    const r = residuals(p), e = sq(r), J = r.map(() => []);
    for (let j = 0; j < 7; j++) {
      const h = j < 3 ? 1 : j < 6 ? 1e-5 : 0.1, q = p.slice(); q[j] += h; const rq = residuals(q);
      for (let i = 0; i < r.length; i++) J[i][j] = (rq[i] - r[i]) / h;
    }
    const A = [...Array(7)].map((_, a) => [...Array(7)].map((_, b) => J.reduce((s, row) => s + row[a] * row[b], 0)));
    const g = [...Array(7)].map((_, a) => -J.reduce((s, row, i) => s + row[a] * r[i], 0));
    for (let a = 0; a < 7; a++) A[a][a] *= 1 + lam;
    const np = p.map((v, i) => v + solveLinear(A, g)[i]);
    if (sq(residuals(np)) < e) { p = np; lam *= 0.3; } else lam *= 10;
  }
  return p;
}

let best = null;
for (const C of cfg.seeds) for (const f of cfg.focalSeeds) {
  const d = cfg.aimAt.map((v, i) => v - C[i]);
  const p = levenbergMarquardt([...C, Math.atan2(d[1], d[0]), Math.atan2(d[2], Math.hypot(d[0], d[1])), 0, f]);
  const e = sq(residuals(p));
  if (!best || e < best.e) best = { e, p };
// Crop of a photo, enlarged, with a pixel grid (labels in the photo's own pixels) and optional overlays of vehicle-frame
// polylines projected through a fitted camera: for reading outline points for trace-profile.mjs and for checking a
// profile against a museum photo. Renders with Playwright's Chromium (the e2e dependency).
// Usage: node tools/photo-grid.mjs <photo.jpg> <out.png> [x0 y0 x1 y1] [scale] [step] [--overlay overlay.json]
// overlay.json: { cam, image, shapes: [{ y (mm plane), pts: [[x, z], …] (mm), color?, closed? }] }; shapes may instead take
// { from: "stops/<slug>/car.js", path: "body.ghost.0.pts" } to draw a profile straight from a car config.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { chromium } from "@playwright/test";
import { camera } from "./camera.mjs";

const args = process.argv.slice(2), oi = args.indexOf("--overlay"), overlay = oi >= 0 ? JSON.parse(readFileSync(args.splice(oi, 2)[1], "utf8")) : null;
const [photo, out, ...nums] = args, b64 = readFileSync(photo).toString("base64");
const browser = await chromium.launch(), page = await browser.newPage();
await page.setContent(`<img id="i" src="data:image/jpeg;base64,${b64}">`);
const [W, H] = await page.$eval("#i", i => [i.naturalWidth, i.naturalHeight]);
const [x0, y0, x1, y1] = nums.length >= 4 ? nums.slice(0, 4).map(Number) : [0, 0, W, H], k = +(nums[4] ?? 1), step = +(nums[5] ?? 50);

const lines = [];
for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) lines.push(`<line x1="${x}" y1="${y0}" x2="${x}" y2="${y1}" stroke="${x % (2 * step) ? "#fa0" : "#f00"}"/><text x="${x + 1}" y="${y0 + 9 / k}" fill="#f33">${x}</text>`);
for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) lines.push(`<line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="${y % (2 * step) ? "#0dd" : "#08f"}"/><text x="${x0 + 1}" y="${y - 1 / k}" fill="#0af">${y}</text>`);
if (overlay) {
  const cam = camera(overlay.cam, overlay.image);
  for (const s of overlay.shapes) {
    let pts = s.pts;
    if (s.from) { pts = (await import(pathToFileURL(resolve(s.from)))).default; for (const key of s.path.split(".")) pts = pts[key]; }
    const xy = pts.map(([x, z]) => cam.project([x, s.y, z]).map(v => v.toFixed(1)).join(","));
    lines.push(`<poly${s.closed ? "gon" : "line"} points="${xy.join(" ")}" fill="none" stroke="${s.color ?? "#f0f"}" stroke-width="${2 / k}"/>`);
  }
}
await page.setViewportSize({ width: Math.round((x1 - x0) * k), height: Math.round((y1 - y0) * k) });
await page.setContent(`<body style="margin:0"><svg width="${(x1 - x0) * k}" height="${(y1 - y0) * k}" viewBox="${x0} ${y0} ${x1 - x0} ${y1 - y0}"
  font-size="${9 / k}" font-family="monospace" stroke-width="${1 / k}"><image href="data:image/jpeg;base64,${b64}" width="${W}" height="${H}"/>${lines.join("")}</svg></body>`);
await page.screenshot({ path: out });
await browser.close();
console.log(`${out}: ${W}×${H} photo, crop ${x0},${y0}–${x1},${y1} at ×${k}`);
